        if (await this.succeeds("merge-base", "--is-ancestor", main, "HEAD"))
            return [];
        if ((await this.git("status", "--porcelain")).trim() !== "")
            return [];
        if (await this.succeedsWithoutHooks("merge", "--quiet", "--no-edit", "-m", `Bring in the latest ${this.settings.baseBranch}`, main))
            return [];
